create table public.orders (id uuid primary key default gen_random_uuid(), store_id uuid not null references public.stores(id), user_id uuid references public.users(id) on delete set null, order_number text not null, status text not null default 'pending' check(status in ('pending','confirmed','processing','shipped','delivered','cancelled','refunded')), currency char(3) not null, subtotal_minor bigint not null default 0 check(subtotal_minor >= 0), discount_minor bigint not null default 0 check(discount_minor >= 0), tax_minor bigint not null default 0 check(tax_minor >= 0), shipping_minor bigint not null default 0 check(shipping_minor >= 0), total_minor bigint not null default 0 check(total_minor >= 0), idempotency_key text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(store_id,order_number), unique(store_id,id));
create unique index uq_order_idempotency on public.orders(store_id,idempotency_key) where idempotency_key is not null;
